/* ---- the syscalls */
/** exit (SYS_EXIT, $00): End the task with an exit code. Nothing is flushed: exit() (stdlib.h) flushes the C streams first.
 *  [code: A] */
void hz_exit(unsigned code);
/** yield (SYS_YIELD, $01): Give the CPU to the next ready task of the same or higher priority.
 *  [no arguments] */
void hz_yield(void);
/** sleep (SYS_SLEEP, $02): Sleep ms milliseconds (10 ms resolution, rounded up; 0 = yield).
 *  [ms: A] */
void hz_sleep(unsigned ms);
/** getpid (SYS_GETPID, $03): The task id (1-62).
 *  [no arguments] */
unsigned hz_getpid(void);
/** uptime (SYS_UPTIME, $04): Milliseconds since reset (32 bits).
 *  [no arguments] */
long hz_uptime(void);
/** putc (SYS_PUTC, $05): One character on the kernel console (unbuffered).
 *  [c: A] */
void hz_putc(unsigned c);
/** puts (SYS_PUTS, $06): A zero-terminated string on the console, written as one piece.
 *  [s: XY] */
int hz_puts(const char *s);
/** con_size (SYS_CSIZE, $07): The console's columns; hz_x = its rows (78 x 29 on the screen; a terminal window's size in a terminal).
 *  [no arguments; out: hz_x] */
unsigned hz_con_size(void);
/** chdir (SYS_CHDIR, $08): Change the current directory (inherited by tasks it spawns).
 *  [path: XY] */
int hz_chdir(const char *path);
/** getcwd (SYS_GETCWD, $09): The current directory (absolute, zero-terminated) into buf -> its length. EINVAL if buf is too small.
 *  [buf: XY, size: A] */
int hz_getcwd(char *buf, unsigned size);
/** restart (SYS_RESTART, $0A): Restart Horizon (0) or the whole machine (1). Programs should rather use sysreq.
 *  [full: A] */
int hz_restart(unsigned full);
/** sync (SYS_SYNC, $0B): Close every open file and flush the card; flags bit 0: end every other program first.
 *  [flags: A] */
int hz_sync(unsigned flags);
/** sysreq (SYS_SYSREQ, $0C): Ask the Desktop to shut down (SR_SHUTDOWN), restart (SR_RESTART) or fully restart (SR_FULLRESTART).
 *  [what: A] */
int hz_sysreq(unsigned what);
/** time_get (SYS_TGET, $0D): The clock: seconds since 2000-01-01 00:00; hz_y = CLK_NONE / CLK_SAVED / CLK_SET (how it was set).
 *  [no arguments; out: hz_y] */
long hz_time_get(void);
/** time_set (SYS_TSET, $0E): Set the clock (state CLK_SAVED or CLK_SET).
 *  [secs: AX32, state: Y] */
int hz_time_set(long secs, unsigned state);
/** vsync (SYS_VSYNC, $0F): Wait for the next vertical blank (60 Hz) -> the frame counter. Also waits for the caller's draw list.
 *  [no arguments] */
unsigned hz_vsync(void);
/** bank_alloc (SYS_BALLOC, $10): A fresh 64 KB bank owned by the task -> its number. ENOMEM when none is left.
 *  [no arguments] */
unsigned hz_bank_alloc(void);
/** bank_free (SYS_BFREE, $11): Give back a bank from bank_alloc.
 *  [bank: A] */
int hz_bank_free(unsigned bank);
/** mem_info (SYS_MINFO, $12): Free banks; hz_x = total banks.
 *  [no arguments; out: hz_x] */
unsigned hz_mem_info(void);
/** open (SYS_OPEN, $20): Open a file (HZ_O_READ, HZ_O_RDWR, HZ_O_CREATE, HZ_O_APPEND) -> handle (0-3; URLs and connections 4-7). For an HTTP error hz_x = the status.
 *  [path: XY, mode: A; out: hz_x] */
int hz_open(const char *path, unsigned mode);
/** close (SYS_CLOSE, $21): Close a handle.
 *  [handle: A] */
int hz_close(unsigned handle);
/** read (SYS_READ, $22): Read io->len bytes into io->buf -> bytes read (fewer = end of file).
 *  [io: XY] */
int hz_read(hz_io *io);
/** write (SYS_WRITE, $23): Write io->len bytes from io->buf -> bytes written.
 *  [io: XY] */
int hz_write(const hz_io *io);
/** seek (SYS_SEEK, $24): Move to an absolute position -> the new position.
 *  [handle: A, pos: XY32] */
long hz_seek(unsigned handle, unsigned long pos);
/** stat (SYS_STAT, $25): Information on blk->path into blk->out (9 bytes: hz_fileinfo) -> the size. For an HTTP error hz_x = the status.
 *  [blk: XY; out: hz_x] */
long hz_stat(hz_statblk *blk);
/** readdir (SYS_READDIR, $26): Directory entries of blk->path packed into blk->buf (skipping blk->skip) -> entries read. See hz_dirent.
 *  [blk: XY] */
int hz_readdir(hz_readdirblk *blk);
/** delete (SYS_DELETE, $27): Delete a file (or an empty folder).
 *  [path: XY] */
int hz_delete(const char *path);
/** mkdir (SYS_MKDIR, $28): Make a folder.
 *  [path: XY] */
int hz_mkdir(const char *path);
/** rename (SYS_RENAME, $29): Rename or move a file or folder.
 *  [blk: XY] */
int hz_rename(const hz_renameblk *blk);
/** spawn (SYS_SPAWN, $30): Start a program -> task id. Returns once it is loaded (load errors come here).
 *  [blk: XY] */
int hz_spawn(const hz_spawnblk *blk);
/** wait (SYS_WAIT, $31): Wait for a child to end -> its exit code (the low 15 bits; see the docs for $FF80 and $FF00+cause).
 *  [task: A] */
int hz_wait(unsigned task);
/** kill (SYS_KILL, $32): End a task (it exits with $FF80).
 *  [task: A] */
int hz_kill(unsigned task);
/** task_info (SYS_TINFO, $33): The task in slot 0-15 into rec (id 0 = a free slot).
 *  [slot: A, rec: XY] */
int hz_task_info(unsigned slot, hz_taskinfo *rec);
/** task_single (SYS_SINGLE, $34): One instance of this program only: when one runs already, -1 with hz_errno ERUNNING and hz_x = its id (the program should exit).
 *  [no arguments; out: hz_x] */
int hz_task_single(void);
/** port_create (SYS_PCREATE, $40): A message port owned by the caller -> its number (0-15).
 *  [no arguments] */
int hz_port_create(void);
/** send (SYS_SEND, $41): Send a 16-byte message (EAGAIN: the queue is full).
 *  [port: A, msg: XY] */
int hz_send(unsigned port, const hz_msg *msg);
/** recv (SYS_RECV, $42): Receive a 16-byte message; blocks unless port | RV_POLL (then EAGAIN when empty).
 *  [port: A, msg: XY] */
int hz_recv(unsigned port, hz_msg *msg);
/** port_close (SYS_PCLOSE, $43): Close an own port.
 *  [port: A] */
int hz_port_close(unsigned port);
/** input_claim (SYS_ICLAIM, $50): Take the keyboard (EAGAIN if another task holds it).
 *  [no arguments] */
int hz_input_claim(void);
/** input_read (SYS_IREAD, $51): Wait for a key or mouse event -> A (key: HID usage; mouse: $0100 | buttons; wheel: $0200); hz_x, hz_y as in ABI.md ("Mouse").
 *  [no arguments; out: hz_x hz_y] */
unsigned hz_input_read(void);
/** input_release (SYS_IRELEASE, $52): Give the keyboard back.
 *  [no arguments] */
int hz_input_release(void);
/** input_lend (SYS_ILEND, $53): Lend the keyboard to a task (flags bit 0: ctrl-C kills it).
 *  [task: A, flags: X] */
int hz_input_lend(unsigned task, unsigned flags);
/** input_poll (SYS_IPOLL, $54): As input_read, but EAGAIN at once when nothing is queued (test hz_errno).
 *  [no arguments; out: hz_x hz_y] */
unsigned hz_input_poll(void);
/** joystick (SYS_JOY, $55): The joysticks' directions (JOY_*: port 1 bits 0-3, port 2 bits 4-7); hz_x = triggers (bit 0 port 1, bit 1 port 2).
 *  [A = $0; out: hz_x] */
unsigned hz_joystick(void);
/** mouse_inject (SYS_MINJECT, $5F): Test aid: one mouse event through the kernel's path (signed bytes).
 *  [dx: A.lo, dy: A.hi, wheel: X.lo, buttons: X.hi] */
int hz_mouse_inject(unsigned dx, unsigned dy, unsigned wheel, unsigned buttons);
/** classic_show (SYS_CLASSIC, $60): Show the classic Atari until F12 (keyboard holder only).
 *  [no arguments] */
int hz_classic_show(void);
/** classic_mount (SYS_CMOUNT, $61): Mount a disk image, executable or cartridge (CK_*) -> the kind mounted.
 *  [path: XY, kind: A.lo, slot: A.hi] */
int hz_classic_mount(const char *path, unsigned kind, unsigned slot);
/** classic_eject (SYS_CEJECT, $62): Eject (CK_DISK with a slot 0-3, CK_XEX, CK_CART).
 *  [kind: A.lo, slot: A.hi] */
int hz_classic_eject(unsigned kind, unsigned slot);
/** classic_boot (SYS_CBOOT, $63): Cold boot the classic Atari and show it (0), or only boot it (CB_STAY).
 *  [mode: A] */
int hz_classic_boot(unsigned mode);
/** classic_query (SYS_CQUERY, $64): The path mounted at item (0-3 D1:-D4:, 4 executable, 5 cartridge) into a 128-byte buffer -> its length (0: none).
 *  [item: A, buf128: XY] */
int hz_classic_query(unsigned item, char *buf128);
/** beep (SYS_BEEP, $65): A POKEY tone on channel 1: pitch (AUDF), duration in 10 ms ticks, volume 0-15.
 *  [pitch: A, ticks: X, volume: Y] */
int hz_beep(unsigned pitch, unsigned ticks, unsigned volume);
/** sound_write (SYS_SNDW, $66): Write a POKEY register ($00-$0F; $10-$13 the DACs before REV $0C).
 *  [reg: A, value: X] */
int hz_sound_write(unsigned reg, unsigned value);
/** sound_chime (SYS_CHIME, $67): The user interface's chime (CH_INFO, CH_WARN, CH_QUESTION, CH_ERROR); volume $FFFF = the setting.
 *  [kind: A, volume: X] */
int hz_sound_chime(unsigned kind, unsigned volume);
/** sample_play (SYS_SPLAY, $68): Play a sample on Lau (REV $0A) -> the voice 0-7. ENODEV without Lau.
 *  [s: XY] */
int hz_sample_play(const hz_sample *s);
/** sample_stop (SYS_SSTOP, $69): Stop a voice of the caller ($FFFF: all of them).
 *  [voice: A] */
int hz_sample_stop(unsigned voice);
/** sample_stat (SYS_SSTAT, $6A): The caller's voices playing (bit n = voice n); hz_x = all voices playing. ENODEV without Lau.
 *  [no arguments; out: hz_x] */
unsigned hz_sample_stat(void);
/** sample_set (SYS_SSET, $6B): Change a playing voice's pitch and volumes.
 *  [voice: A, pitch: X, left: Y.lo, right: Y.hi] */
int hz_sample_set(unsigned voice, unsigned pitch, unsigned left, unsigned right);
/** sample_timer (SYS_STIMER, $6C): The music timer: a message to port every period (microseconds, 1000 or more); port $FFFF: off -> the generation.
 *  [port: A, period_us: XY32] */
unsigned hz_sample_timer(unsigned port, unsigned long period_us);
/** opl_write (SYS_OPLW, $6D): Write an OPL2 register (REV $0C; $FFFE probe, $FFFF reset, $FFFD release) -> OPL_STAT.
 *  [reg: A, value: X] */
unsigned hz_opl_write(unsigned reg, unsigned value);
/** ws_start (SYS_WSSTART, $70): Start the window system -> 1 started now, 0 already running.
 *  [no arguments] */
unsigned hz_ws_start(void);
/** ws_stop (SYS_WSSTOP, $71): End the window system (its starter only).
 *  [no arguments] */
int hz_ws_stop(void);
/** win_open (SYS_WOPEN, $72): Open a window -> its number (0-15).
 *  [w: XY] */
int hz_win_open(const hz_winopen *w);
/** win_close (SYS_WCLOSE, $73): Close an own window.
 *  [win: A] */
int hz_win_close(unsigned win);
/** win_draw (SYS_WDRAW, $74): Draw in a window (WD_* ops; see hz_windraw).
 *  [win: A, d: XY] */
int hz_win_draw(unsigned win, const hz_windraw *d);
/** win_event (SYS_WEVENT, $75): The next event of the caller's windows into ev; poll = 1: EAGAIN at once when there is none.
 *  [poll: A, ev: XY] */
int hz_win_event(unsigned poll, hz_event *ev);
/** win_twidth (SYS_WTWIDTH, $76): The width in pixels of s in a font (0 UI, 1 fixed 8x12).
 *  [font: A, s: XY] */
unsigned hz_win_twidth(unsigned font, const char *s);
/** ws_sync (SYS_WSSYNC, $77): Wait until the screen shows everything drawn so far.
 *  [no arguments] */
int hz_ws_sync(void);
/** win_move (SYS_WMOVE, $78): Move a window.
 *  [win: A, x: X, y: Y] */
int hz_win_move(unsigned win, int x, int y);
/** ws_redraw (SYS_WSREDRAW, $79): Repaint the whole screen (for measurements).
 *  [no arguments] */
int hz_ws_redraw(void);
/** ws_stats (SYS_WSSTATS, $7A): Microseconds the last repaint took.
 *  [no arguments] */
long hz_ws_stats(void);
/** ws_config (SYS_WSCONFIG, $7B): Measurement switches (bit 0 blitter off, ...) -> 1 if the blitter is used; hz_x = the hardware revision.
 *  [flags: A; out: hz_x] */
unsigned hz_ws_config(unsigned flags);
/** win_timer (SYS_WTIMER, $7C): WE_TICK events every ticks x 10 ms (0 = off).
 *  [win: A, ticks: X] */
int hz_win_timer(unsigned win, unsigned ticks);
/** win_menu (SYS_WMENU, $7D): The window's menus: "title", "item", ..., "", "title", ..., "", "" in one block.
 *  [win: A, menus: XY] */
int hz_win_menu(unsigned win, const char *menus);
/** ws_status (SYS_WSTATUS, $7E): The text at the right of the menu bar (31 characters).
 *  [s: XY] */
int hz_ws_status(const char *s);
/** ws_term (SYS_WTERM, $7F): Send this task's console (and its children's) to a WF_TERM window ($FF: detach).
 *  [win: A] */
int hz_ws_term(unsigned win);
/** clip_put (SYS_CLPUT, $80): Put bytes on the clipboard (length 0 empties it).
 *  [c: XY] */
int hz_clip_put(const hz_clipblk *c);
/** clip_get (SYS_CLGET, $81): Copy the clipboard into c->data (at most c->len bytes) -> the clipboard's length.
 *  [c: XY] */
unsigned hz_clip_get(hz_clipblk *c);
/** win_info (SYS_WINFO, $82): A window's content rectangle on the screen (any program's window).
 *  [win: A, r: XY] */
int hz_win_info(unsigned win, hz_rect *r);
/** win_at (SYS_WINAT, $83): The top-most window at a screen position -> its number, $FF none.
 *  [x: X, y: Y] */
unsigned hz_win_at(int x, int y);
/** win_drop (SYS_WDROP, $84): Drop a string on a window (any program's): it gets WE_DROP.
 *  [win: A, s: XY] */
int hz_win_drop(unsigned win, const char *s);
/** win_dropget (SYS_WDROPGET, $85): The last string dropped on an own window (128-byte buffer).
 *  [win: A, buf128: XY] */
int hz_win_dropget(unsigned win, char *buf128);
/** ws_palette (SYS_WSPAL, $86): Set one palette entry (16-255: the caller's own; see ABI.md "Palette entries").
 *  [index: A, red: X.lo, green: X.hi, blue: Y] */
int hz_ws_palette(unsigned index, unsigned red, unsigned green, unsigned blue);
/** setting (SYS_SETTING, $87): A system setting (0 mouse speed, 1 alert volume, ...); value $FFFF only reads -> the old value.
 *  [id: A, value: X] */
unsigned hz_setting(unsigned id, unsigned value);
/** win_title (SYS_WTITLE, $88): A new window title (31 characters).
 *  [win: A, s: XY] */
int hz_win_title(unsigned win, const char *s);
/** ws_pointer (SYS_WPTR, $89): The pointer's shape (PTR_*).
 *  [shape: A] */
int hz_ws_pointer(unsigned shape);
/** ws_mouse (SYS_WMOUSE, $8A): The pointer now (screen, and relative to win's content; $FF none) -> the buttons; hz_x = the window under it ($FF none).
 *  [win: A, m: XY; out: hz_x] */
unsigned hz_ws_mouse(unsigned win, hz_mouse *m);
/** ws_hold (SYS_WSHOLD, $8B): Hold the screen while one change is drawn in several calls (1), release (0).
 *  [on: A] */
int hz_ws_hold(unsigned on);
/** win_mstate (SYS_WMSTATE, $8C): A menu item's state (MS_CHECK, MS_DIM); the item must start with a state byte.
 *  [win: A, menu: X.lo, item: X.hi, state: Y] */
int hz_win_mstate(unsigned win, unsigned menu, unsigned item, unsigned state);
/** ws_closeall (SYS_WSCLOSEALL, $8D): Send WE_CLOSE to every window of every other program.
 *  [no arguments] */
int hz_ws_closeall(void);
/** win_geom (SYS_WGEOM, $8E): Move and resize an own window (x = $8000: it stays).
 *  [win: A, r: XY] */
int hz_win_geom(unsigned win, const hz_rect *r);
/** task_name (SYS_TNAME, $8F): The name the menu bar shows for a task's windows (0 = the caller). See hz_task_name_get.
 *  [task: A, name: XY] */
int hz_task_name(unsigned task, const char *name);
/** win_popup (SYS_WPOPUP, $90): A pop-up menu (blocks) -> the item chosen, $FFFF none (test hz_errno).
 *  [win: A, p: XY] */
unsigned hz_win_popup(unsigned win, const hz_popup *p);
/** spr_alloc (SYS_SPRALLOC, $91): count hardware sprites in a row for an own window -> the first one (REV $0B).
 *  [count: A, win: X] */
int hz_spr_alloc(unsigned count, unsigned win);
/** spr_free (SYS_SPRFREE, $92): Free sprites (first $FFFF: all of the caller's).
 *  [first: A, count: X] */
int hz_spr_free(unsigned first, unsigned count);
/** spr_set (SYS_SPRSET, $93): Set count sprites (all of their fields) from the next frame on.
 *  [count: A, e: XY] */
int hz_spr_set(unsigned count, const hz_sprite *e);
/** spr_move (SYS_SPRMOVE, $94): Move one sprite (the cheap per-frame call). Several at once: hz_spr_move_many.
 *  [sprite: A, x: X, y: Y] */
int hz_spr_move(unsigned sprite, int x, int y);
/** spr_show (SYS_SPRSHOW, $95): Show (1) or hide (0) a sprite.
 *  [sprite: A, on: X] */
int hz_spr_show(unsigned sprite, unsigned on);
/** fs_enter (SYS_FSENTER, $96): Full-screen mode for an own window with the given framebuffer.
 *  [win: A, f: XY] */
int hz_fs_enter(unsigned win, const hz_fsenter *f);
/** fs_leave (SYS_FSLEAVE, $97): Back to the desktop.
 *  [win: A] */
int hz_fs_leave(unsigned win);
/** fs_scroll (SYS_FSSCROLL, $98): The full-screen program's scroll registers (REV $0B).
 *  [s: XY] */
int hz_fs_scroll(const hz_fsscroll *s);
/** fs_raster (SYS_FSRASTER, $99): The raster table: count palette changes at given lines (0: off; REV $09).
 *  [count: A, e: XY] */
int hz_fs_raster(unsigned count, const hz_raster *e);
/** pal_set (SYS_PALSET, $9A): Set count palette entries from first (count 0 = 256) from red, green, blue bytes.
 *  [first: A.lo, count: A.hi, rgb: XY] */
int hz_pal_set(unsigned first, unsigned count, const unsigned char *rgb);
/** pal_alloc (SYS_PALALLOC, $9B): count palette entries in a row for the caller -> the first ($FFFF: any place; count 0: give all back).
 *  [count: A, first: X] */
int hz_pal_alloc(unsigned count, unsigned first);
/** draw_list (SYS_DRAWLIST, $9C): Run count (1-128) draw-list records with the blitter -> records drawn. Returns at once: see list_wait.
 *  [win: A.lo, count: A.hi, r: XY] */
int hz_draw_list(unsigned win, unsigned count, const hz_drawrec *r);
/** list_wait (SYS_LISTWAIT, $9D): 0: wait until the caller's draw list is done; 1: ask -> 1 while it runs.
 *  [ask: A] */
unsigned hz_list_wait(unsigned ask);
/** frame (SYS_FRAME, $9E): The frame counter (+1 every vertical blank; REV $09).
 *  [no arguments] */
unsigned hz_frame(void);
/** win_vbl (SYS_WINVBL, $9F): WE_VBL events at every vertical blank (REV $09).
 *  [win: A, on: X] */
int hz_win_vbl(unsigned win, unsigned on);
/** win_front (SYS_WFRONT, $A0): Raise an own window (restored if minimized) and give it the focus.
 *  [win: A] */
int hz_win_front(unsigned win);
/** sheet_new (SYS_SHEETNEW, $A1): Register a sheet of art in own memory -> its number (1-32).
 *  [s: XY] */
int hz_sheet_new(const hz_sheetnew *s);
/** sheet_free (SYS_SHEETFREE, $A2): Free a sheet ($FFFF: all of the caller's).
 *  [sheet: A] */
int hz_sheet_free(unsigned sheet);
/** sheet_draw (SYS_SHEETDRAW, $A3): Run count (1-128) sheet records -> records drawn. Returns at once: see list_wait.
 *  [win: A.lo, count: A.hi, r: XY] */
int hz_sheet_draw(unsigned win, unsigned count, const hz_sheetrec *r);
/** spr_move (SYS_SPRMOVE, $94): (0.24) Move count sprites (1-16) in one call.
 *  [count: A, e: XY, A |= $8000] */
int hz_spr_move_many(unsigned count, const hz_sprmove *e);
/** task_name (SYS_TNAME, $8F): Read a task's name as the menu bar shows it (16-byte buffer; 0 = the caller).
 *  [task: A, buf16: XY, A |= $8000] */
int hz_task_name_get(unsigned task, char *buf16);

#endif
